//! 🛫️ Borrowed Flow native record production against the owner's declared schemas.
use super::*;
use semio_framework_dsl_record::DslField;
use semio_framework_dsl_record::FieldValue;
use semio_framework_dsl_record::RecordValue;
use semio_framework_dsl_record::native_encoding::EncodedRecord;
use semio_framework_dsl_record::native_encoding::retire_field;
use semio_framework_dsl_record::__rt::DecodedFieldOwner;
use semio_framework_value::{NativeEncodeControl,ToValue,ValueError};
use std::mem::size_of;
type Result<T>=std::result::Result<T,ValueError>;
fn block(value:FieldValue,control:&mut NativeEncodeControl<'_>)->Result<FieldValue>{let value=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(value,retire_field);control.charge(size_of::<FieldValue>())?;Ok(semio_framework_dsl_record::FieldValue::Block(Box::new(value.take())))}
fn field<T:DslField>(record:&mut EncodedRecord,id:u16,value:&T,control:&mut NativeEncodeControl<'_>)->Result<()>{let value=control.scoped_stage(|control|{control.begin_stage(0)?;value.to_value_controlled(control)})?;record.insert(id,value)?;control.step()}
fn retire_pairs(values:Vec<(String,FieldValue)>){for(_,value)in values{retire_field(value);}}
fn retire_records(values:Vec<(String,RecordValue)>){for(_,record)in values{retire_field(semio_framework_dsl_record::FieldValue::Record(record));}}
fn dictionary(value:&Dictionary,control:&mut NativeEncodeControl<'_>)->Result<FieldValue>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(value.len())?;let mut output=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(value.len())?,retire_pairs);for(key,value)in value.iter(){let key=control.copy_text(key)?;let value=semio_framework_dsl_record::FieldValue::Record(neural_value(value,control)?);output.as_mut().push((key,value));control.step()?;}Ok(semio_framework_dsl_record::FieldValue::Map(output.take()))}))}
fn optional_dictionary(value:&Dictionary,control:&mut NativeEncodeControl<'_>)->Result<FieldValue>{if value.is_empty(){control.step()?;Ok(semio_framework_dsl_record::FieldValue::Absent)}else{dictionary(value,control)}}
fn neural_value(value:&NeuralValue,control:&mut NativeEncodeControl<'_>)->Result<RecordValue>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(6)?;let mut record=semio_framework_dsl_record::native_encoding::EncodedRecord::new(6,control)?;for id in 0..6{record.insert(id,semio_framework_dsl_record::FieldValue::Absent)?;}match value{
 NeuralValue::Atom(Atom::Null)=>field(&mut record,0,&true,control)?,
 NeuralValue::Atom(Atom::Boolean(value))=>field(&mut record,1,value,control)?,
 NeuralValue::Atom(Atom::Integer(value))=>field(&mut record,2,value,control)?,
 NeuralValue::Atom(Atom::Decimal(value))=>field(&mut record,3,value,control)?,
 NeuralValue::Atom(Atom::String(value))=>field(&mut record,4,value,control)?,
 NeuralValue::Dictionary(value)=>record.insert(5,dictionary(value,control)?)?,
}Ok(record.take())}))}
fn wire(id:&str,from:&str,to:&str,from_port:&str,to_port:&str,control:&mut NativeEncodeControl<'_>)->Result<RecordValue>{control.scoped_stage(|control|{control.begin_stage(0)?;let mut record=semio_framework_dsl_record::native_encoding::EncodedRecord::new(2,control)?;record.insert(0,semio_framework_dsl_record::FieldValue::Text(control.copy_text(id)?))?;let from=semio_framework_dsl_record::WireNode{id:control.copy_text(from)?,kind:None,port:if from_port.is_empty(){None}else{Some(control.copy_text(from_port)?)}};
 let to=semio_framework_dsl_record::WireNode{id:control.copy_text(to)?,kind:None,port:if to_port.is_empty(){None}else{Some(control.copy_text(to_port)?)}};
 record.insert(1,semio_framework_dsl_record::FieldValue::Wire(semio_framework_dsl_record::WireValue{from,edge:Some((true,to)),edge_label:semio_framework_dsl_record::WireEdgeLabel::default(),properties:semio_framework_value::DslValue::Object(Vec::new())}))?;control.step()?;Ok(record.take())})}
fn strings<'a>(values:impl ExactSizeIterator<Item=&'a String>,control:&mut NativeEncodeControl<'_>)->Result<FieldValue>{control.scoped_stage(|control|{control.begin_stage(values.len())?;let mut output=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(values.len())?,|items:Vec<FieldValue>|{for item in items{retire_field(item);}});for value in values{output.as_mut().push(semio_framework_dsl_record::FieldValue::Text(control.copy_text(value)?));control.step()?;}Ok(semio_framework_dsl_record::FieldValue::List(output.take()))})}
fn tree(value:&Tree,control:&mut NativeEncodeControl<'_>)->Result<RecordValue>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let mut record=semio_framework_dsl_record::native_encoding::EncodedRecord::new(2,control)?;
 let mut neurons=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(value.neurons.len())?,retire_records);for value in &value.neurons{let mut neuron=semio_framework_dsl_record::native_encoding::EncodedRecord::new(4,control)?;field(&mut neuron,0,&value.id,control)?;field(&mut neuron,1,&value.kind,control)?;neuron.insert(2,optional_dictionary(&value.params,control)?)?;neuron.insert(3,match &value.tree{Some(value)=>block(semio_framework_dsl_record::FieldValue::Record(tree(value,control)?),control)?,None=>semio_framework_dsl_record::FieldValue::Absent})?;neurons.as_mut().push((control.copy_text("neuron")?,neuron.take()));control.step()?;}record.insert(0,block(semio_framework_dsl_record::FieldValue::Statements(neurons.take()),control)?)?;
 let mut synapses=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(value.synapses.len())?,|items:Vec<FieldValue>|{for item in items{retire_field(item);}});for value in &value.synapses{synapses.as_mut().push(semio_framework_dsl_record::FieldValue::Record(wire(&value.id,&value.from,&value.to,&value.from_port,&value.to_port,control)?));control.step()?;}record.insert(1,semio_framework_dsl_record::FieldValue::List(synapses.take()))?;Ok(record.take())}))}
fn widget(value:&Widget,control:&mut NativeEncodeControl<'_>)->Result<(String,RecordValue)>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let count=match value{Widget::Neuron{..}|Widget::InputSlider{..}=>6,Widget::Variable{..}|Widget::OutputPreview{..}=>3,Widget::Cluster{..}=>4,_=>2};let mut record=semio_framework_dsl_record::native_encoding::EncodedRecord::new(count,control)?;let keyword=match value{
 Widget::Neuron{id,neuron_kind,params,input_ports,output_ports,preview}=>{field(&mut record,0,id,control)?;field(&mut record,1,neuron_kind,control)?;record.insert(2,optional_dictionary(params,control)?)?;record.insert(3,strings(input_ports.iter(),control)?)?;record.insert(4,strings(output_ports.iter(),control)?)?;field(&mut record,5,preview,control)?;"neuron"},
 Widget::InputSlider{id,label,value,min,max,step}=>{field(&mut record,0,id,control)?;field(&mut record,1,label,control)?;field(&mut record,2,value,control)?;field(&mut record,3,min,control)?;field(&mut record,4,max,control)?;field(&mut record,5,step,control)?;"input-slider"},
 Widget::InputNote{id,text}=>{field(&mut record,0,id,control)?;field(&mut record,1,text,control)?;"input-note"},
 Widget::InputImage{id,src}=>{field(&mut record,0,id,control)?;field(&mut record,1,src,control)?;"input-image"},
 Widget::Variable{id,name,schema}=>{field(&mut record,0,id,control)?;field(&mut record,1,name,control)?;field(&mut record,2,schema,control)?;"variable"},
 Widget::OutputPreview{id,preview,expanded}=>{field(&mut record,0,id,control)?;record.insert(1,optional_dictionary(preview,control)?)?;record.insert(2,strings(expanded.iter(),control)?)?;"output-preview"},
 Widget::OutputAction{id,action}=>{field(&mut record,0,id,control)?;field(&mut record,1,action,control)?;"output-action"},
 Widget::OutputExport{id,format}=>{field(&mut record,0,id,control)?;field(&mut record,1,format,control)?;"output-export"},
 Widget::Cluster{id,name,tree:value,flow}=>{field(&mut record,0,id,control)?;field(&mut record,1,name,control)?;record.insert(2,block(semio_framework_dsl_record::FieldValue::Record(tree(value,control)?),control)?)?;record.insert(3,semio_framework_dsl_record::FieldValue::Value(gui(flow,control)?))?;"cluster"},
};Ok((control.copy_text(keyword)?,record.take()))}))}
/// 🌊️ Borrows the actual persisted owner and preserves its layout iteration order.
pub(super) fn encode_record(value:&FlowHostSnapshot,control:&mut NativeEncodeControl<'_>)->Result<RecordValue>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let mut record=semio_framework_dsl_record::native_encoding::EncodedRecord::new(5,control)?;field(&mut record,0,&value.schema,control)?;record.insert(1,block(semio_framework_dsl_record::FieldValue::Record(value.camera.__dsl_to_record_controlled(control)?),control)?)?;
 let mut widgets=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(value.widgets.len())?,retire_records);for value in &value.widgets{widgets.as_mut().push(widget(value,control)?);control.step()?;}record.insert(2,block(semio_framework_dsl_record::FieldValue::Statements(widgets.take()),control)?)?;
 let mut synapses=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(value.synapses.len())?,|items:Vec<FieldValue>|{for item in items{retire_field(item);}});for value in &value.synapses{synapses.as_mut().push(semio_framework_dsl_record::FieldValue::Record(wire(&value.id,&value.from,&value.to,&value.from_port,&value.to_port,control)?));control.step()?;}record.insert(3,semio_framework_dsl_record::FieldValue::List(synapses.take()))?;
 let mut layout=semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(value.layout.len())?,retire_pairs);for(key,value)in &value.layout{let key=control.copy_text(key)?;layout.as_mut().push((key,semio_framework_dsl_record::FieldValue::Record(value.__dsl_to_record_controlled(control)?)));control.step()?;}record.insert(4,semio_framework_dsl_record::FieldValue::Map(layout.take()))?;Ok(record.take())}))}

fn value_pairs(count:usize,control:&mut NativeEncodeControl<'_>)->Result<DecodedFieldOwner<Vec<(String,semio_framework_value::DslValue)>>>{Ok(semio_framework_dsl_record::__rt::DecodedFieldOwner::new(control.allocate_vec(count)?,|items|<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded(semio_framework_value::DslValue::Object(items))))}
fn value_pair(values:&mut Vec<(String,semio_framework_value::DslValue)>,key:&str,value:semio_framework_value::DslValue,control:&mut NativeEncodeControl<'_>)->Result<()>{let value=semio_framework_value::DecodedValue::new(value,<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded);values.push((control.copy_text(key)?,value.take()));control.step()}
fn gui(value:&FlowGui,control:&mut NativeEncodeControl<'_>)->Result<semio_framework_value::DslValue>{control.scoped_depth(64,|control|control.scoped_stage(|control|{control.begin_stage(0)?;let mut output=value_pairs(3,control)?;value_pair(output.as_mut(),"camera",ToValue::to_value_controlled(&value.camera,control)?,control)?;
 let mut nodes=value_pairs(value.nodes.len(),control)?;for(key,value)in &value.nodes{value_pair(nodes.as_mut(),key,ToValue::to_value_controlled(value,control)?,control)?;}value_pair(output.as_mut(),"nodes",semio_framework_value::DslValue::Object(nodes.take()),control)?;
 let mut previews=semio_framework_value::DecodedValue::new(control.allocate_vec(value.previews.len())?,|items|<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded(semio_framework_value::DslValue::Array(items)));for value in &value.previews{let mut preview=value_pairs(6,control)?;value_pair(preview.as_mut(),"id",ToValue::to_value_controlled(&value.id,control)?,control)?;value_pair(preview.as_mut(),"source",ToValue::to_value_controlled(&value.source,control)?,control)?;value_pair(preview.as_mut(),"mode",ToValue::to_value_controlled(&value.mode,control)?,control)?;value_pair(preview.as_mut(),"preview",ToValue::to_value_controlled(&value.preview,control)?,control)?;
 let mut expanded=semio_framework_value::DecodedValue::new(control.allocate_vec(value.expanded.len())?,|items|<semio_framework_value::DslValue as semio_framework_value::FromValue>::retire_decoded(semio_framework_value::DslValue::Array(items)));for path in &value.expanded{expanded.get_mut().push(ToValue::to_value_controlled(path,control)?);control.step()?;}value_pair(preview.as_mut(),"expanded",semio_framework_value::DslValue::Array(expanded.take()),control)?;value_pair(preview.as_mut(),"layout",ToValue::to_value_controlled(&value.layout,control)?,control)?;previews.get_mut().push(semio_framework_value::DslValue::Object(preview.take()));control.step()?;}value_pair(output.as_mut(),"previews",semio_framework_value::DslValue::Array(previews.take()),control)?;Ok(semio_framework_value::DslValue::Object(output.take()))}))}
